<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Invoice {{ $payment->invoice_number }}</title><style>body{font:14px Arial;margin:40px;color:#19342e}.head{display:flex;justify-content:space-between;border-bottom:2px solid #087f6b;padding-bottom:16px}table{width:100%;border-collapse:collapse;margin-top:24px}td,th{border:1px solid #ccd9d5;padding:9px;text-align:left}.right{text-align:right}.note{margin-top:26px;color:#536b64}@media print{button{display:none}body{margin:20px}}</style></head><body><button onclick="print()">Cetak / Simpan PDF</button><div class="head"><div><h1>INVOICE BMT</h1><b>SMK Muhammadiyah 4 Cileungsi</b></div><div><b>{{ $payment->invoice_number }}</b><br>{{ $payment->created_at->format('d M Y H:i') }}</div></div><p>Nama calon siswa: <b>{{ $payment->siswa->nama }}</b><br>Metode: {{ strtoupper($payment->method) }}@if($payment->bankAccount)<br>Rekening: {{ $payment->bankAccount->bank_name }} {{ $payment->bankAccount->account_number }} a/n {{ $payment->bankAccount->account_holder }}@endif</p><table><thead><tr><th>Rincian biaya</th><th class="right">Nominal</th></tr></thead><tbody>@if($payment->payment_type === 'formulir')<tr><td>Biaya formulir</td><td class="right">Rp {{ number_format($payment->amount,0,',','.') }}</td></tr>@else @foreach($payment->details as $detail)<tr><td>{{ $detail->fee_name }}</td><td class="right">Rp {{ number_format($detail->amount,0,',','.') }}</td></tr>@endforeach @endif<tr><th>Total pembayaran</th><th class="right">Rp {{ number_format($payment->amount,0,',','.') }}</th></tr></tbody></table><p class="note">Disetujui panitia: <b>{{ $payment->approver?->name ?? 'Belum disetujui' }}</b><br>Diterima bendahara: <b>{{ $payment->treasurer?->name ?? 'Belum diterima' }}</b></p></body></html>
